'use client';

import Image from 'next/image';
import Link from 'next/link';
import { useEffect, useState } from 'react';
import { ArrowRight, Check, Clock, Compass, Heart, MapPin, MessageCircle, Sparkles, Star } from 'lucide-react';
import type { BlogPost, Destination, Hotel, Testimonial, Tour } from '../lib/types';
import { HotelShortlistButton, ShortlistButton } from './ShortlistButton';

const CURRENCY_KEY='gss_currency_v1';
const RESIDENT_KEY='gss_resident_mode_v1';
function usePricingPrefs(){const[currency,setCurrency]=useState<'USD'|'KES'>('USD');const[resident,setResident]=useState(false);useEffect(()=>{const load=()=>{const c=localStorage.getItem(CURRENCY_KEY);setCurrency(c==='KES'?'KES':'USD');setResident(localStorage.getItem(RESIDENT_KEY)==='true')};load();window.addEventListener('gss-pricing-preference-changed',load);return()=>window.removeEventListener('gss-pricing-preference-changed',load)},[]);return{currency,resident}}
function formatPrice(usd:number,kes:number|undefined,currency:'USD'|'KES'){if(currency==='KES')return `KSH ${Number(kes&&kes>0?kes:Math.round(usd*130)).toLocaleString()}`;return `$${Number(usd||0).toLocaleString()}`}
function safeImage(src?:string,fallback='/images/catalog/mara-savannah.jpg'){return src||fallback}

export function TourCard({tour}:{tour:Tour}){
  const image=safeImage(tour.images?.[0]);const{currency,resident}=usePricingPrefs();const formattedPrice=formatPrice(tour.priceFrom,tour.residentPriceKES,currency);
  return <article id={`tour-card-${tour.id}`} className="group relative min-h-[470px] sm:min-h-[500px] overflow-hidden rounded-2xl border border-white/10 bg-shell shadow-lg transition-all duration-300 hover:-translate-y-1 hover:shadow-2xl focus-within:ring-2 focus-within:ring-brand-soft">
    <Image src={image} alt={tour.title} fill sizes="(max-width:720px) 100vw,33vw" className="object-cover transition-transform duration-700 group-hover:scale-[1.03]"/>
    <div className="absolute inset-0 bg-gradient-to-t from-shell via-shell/45 to-black/5"/>
    {(tour.featured||tour.popular)&&<span className="absolute left-4 top-4 z-20 inline-flex items-center gap-1.5 rounded-full bg-action/95 px-3 py-1.5 text-xs font-bold text-white shadow-md backdrop-blur-sm"><Sparkles className="h-3.5 w-3.5 text-brand-soft"/>{tour.popular?'Popular Choice':'Featured Safari'}</span>}
    <div className="absolute right-4 top-4 z-30"><ShortlistButton compact safari={{id:tour.id,title:tour.title,slug:tour.slug,image,durationLabel:tour.durationLabel,country:tour.country,priceFrom:tour.priceFrom}}/></div>
    <Link href={`/safaris/${tour.slug}`} aria-label={`Explore ${tour.title}`} className="absolute inset-0 z-10 rounded-2xl"/>
    <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 p-5 sm:p-6"><h3 className="font-serif-luxury text-2xl sm:text-[1.75rem] font-bold leading-tight text-white max-w-[90%]">{tour.title}</h3><div className="mt-4 flex flex-wrap items-center gap-3 text-sm font-semibold text-white/95"><span className="inline-flex items-center gap-1.5"><Clock className="h-4 w-4 text-brand-soft"/>{tour.durationLabel||`${tour.durationDays} Days`}</span><span className="h-4 w-px bg-white/35"/><span className="inline-flex items-center gap-1.5"><MapPin className="h-4 w-4 text-brand-soft"/>{tour.country}</span></div><div className="mt-5 flex items-end justify-between gap-4 border-t border-white/15 pt-4"><div><span className="block text-sm font-medium text-brand-soft">{resident?'Resident rate from':'From'}</span><strong className="mt-0.5 block font-serif-luxury text-2xl font-extrabold text-brand-soft">{formattedPrice}</strong></div><span className="min-h-12 inline-flex items-center justify-center gap-2 rounded-xl bg-brand-strong px-4 text-sm font-bold text-white shadow-md">Explore Safari<ArrowRight className="h-4 w-4"/></span></div></div>
  </article>
}

export function DestinationCard({destination}:{destination:Destination}){const image=safeImage(destination.heroImage);return <article id={`dest-card-${destination.id}`} className="group relative overflow-hidden rounded-2xl bg-white border border-border-strong transition-all duration-500 hover:-translate-y-1 hover:border-brand hover:shadow-xl focus-within:border-brand focus-within:shadow-xl shadow-sm"><Link href={`/destinations/${destination.slug}`} aria-label={`Explore ${destination.name}, ${destination.country}`} className="block w-full text-left rounded-2xl"><div className="relative aspect-[4/3] sm:aspect-[16/11] w-full overflow-hidden bg-shell"><Image src={image} alt={`${destination.name}, ${destination.country}`} fill sizes="(max-width:720px) 100vw,33vw" className="object-cover transition-transform duration-700 group-hover:scale-105"/><div className="absolute inset-0 bg-gradient-to-t from-black via-black/55 to-black/10"/><div className="absolute top-3 left-3"><span className="rounded-full bg-black/75 backdrop-blur-md px-3 py-1 text-xs font-bold text-white border border-white/30 uppercase tracking-wider">{destination.country}</span></div><div className="absolute inset-x-0 bottom-0 p-5 flex flex-col justify-end"><div className="flex items-center gap-1.5 text-xs text-brand-soft font-bold mb-1"><Compass className="w-3.5 h-3.5"/><span>{destination.recommendedDuration||'2 - 4 Days'}</span></div><h3 className="font-serif-luxury text-xl font-bold text-white group-hover:text-brand-soft transition-colors leading-snug">{destination.name}</h3><p className="mt-1 text-sm text-white/95 line-clamp-2 leading-relaxed font-medium">{destination.subtitle||destination.description}</p>{destination.wildlife?.length>0&&<div className="mt-3 flex flex-wrap gap-1.5">{destination.wildlife.slice(0,3).map(animal=><span key={animal} className="rounded-md bg-black/70 backdrop-blur-sm px-2 py-1 text-xs font-medium text-white border border-white/25">{animal}</span>)}{destination.wildlife.length>3&&<span className="text-xs text-brand-soft font-bold self-center ml-1">+{destination.wildlife.length-3} more</span>}</div>}<div className="mt-4 flex items-center justify-between pt-3 border-t border-white/30"><span className="text-sm font-bold text-brand-soft group-hover:underline flex items-center gap-1">Explore destination <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-1"/></span></div></div></div></Link></article>}

export function HotelCard({hotel}:{hotel:Hotel}){const image=safeImage(hotel.images?.[0],'/images/catalog/baobab-beach-resort-spa.jpg');const{currency,resident}=usePricingPrefs();const formattedPrice=formatPrice(hotel.priceFromUSD,hotel.priceFromKES,currency);return <article id={`hotel-card-${hotel.id}`} className="group relative flex flex-col rounded-2xl bg-white border border-border-strong overflow-hidden transition-all duration-300 hover:-translate-y-1 hover:border-brand hover:shadow-xl focus-within:border-brand focus-within:shadow-xl shadow-sm"><div className="relative aspect-[16/10] w-full overflow-hidden bg-surface-soft"><Image src={image} alt={hotel.name} fill sizes="(max-width:720px) 100vw,25vw" className="object-cover transition-transform duration-700 group-hover:scale-105"/><div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent"/><div className="absolute top-3 left-3 right-3 flex items-center justify-between pointer-events-none"><div className="flex flex-wrap gap-1.5">{hotel.isKenyanResidentOffer&&<span className="rounded-full bg-action text-white font-bold px-2.5 py-1 text-xs shadow-sm">Resident Rate</span>}<span className="rounded-full bg-black/70 backdrop-blur-md text-white font-semibold px-2.5 py-1 text-xs border border-white/30">{hotel.category}</span></div>{hotel.rating&&<div className="flex items-center gap-1 rounded-full bg-black/75 backdrop-blur-md px-2.5 py-1 text-xs font-bold text-yellow-400 border border-white/30"><Star className="w-3.5 h-3.5 fill-current"/><span>{hotel.rating}</span></div>}</div><div className="absolute right-3 bottom-3 z-20"><HotelShortlistButton compact hotel={{id:hotel.id,title:hotel.name,slug:hotel.slug,image,location:hotel.location,country:hotel.country,priceFrom:hotel.priceFromUSD,priceFromKES:hotel.priceFromKES}}/></div></div><div className="flex flex-1 flex-col p-5 justify-between bg-white"><div><div className="flex items-center gap-1 text-xs font-bold text-brand-deep mb-1.5"><MapPin className="w-3.5 h-3.5 shrink-0"/><span>{hotel.location}</span></div><h3 className="font-serif-luxury text-lg font-bold text-ink-strong leading-snug"><Link href={`/hotels/${hotel.slug}`} className="transition-colors hover:text-brand-deep rounded-sm">{hotel.name}</Link></h3><p className="mt-2 text-sm text-ink-muted line-clamp-2 leading-relaxed">{hotel.description}</p><div className="mt-3 flex flex-wrap gap-1.5">{hotel.isFamilyFriendly&&<span className="rounded-md bg-action-soft px-2 py-0.5 text-xs font-semibold text-action border border-action-border">Family Friendly</span>}{hotel.isHoneymoonFriendly&&<span className="rounded-md bg-pink-50 px-2 py-0.5 text-xs font-semibold text-pink-800 border border-pink-200">Honeymoon</span>}{hotel.isSeniorFriendly&&<span className="rounded-md bg-blue-50 px-2 py-0.5 text-xs font-semibold text-blue-800 border border-blue-200">Senior Friendly</span>}</div>{hotel.facilities?.length>0&&<div className="mt-3 space-y-1.5">{hotel.facilities.slice(0,2).map(fac=><div key={fac} className="flex items-center gap-1.5 text-xs text-ink-muted"><Check className="w-3.5 h-3.5 text-brand-deep shrink-0"/><span className="truncate">{fac}</span></div>)}</div>}</div><div className="mt-5 pt-4 border-t border-border flex items-end justify-between gap-3"><div><span className="block text-xs uppercase tracking-wider text-ink-muted font-semibold">{resident?'Resident rate from':'Guide rate from'}</span><div className="flex items-baseline gap-1"><span className="text-xl font-extrabold text-ink-strong font-serif-luxury">{formattedPrice}</span><span className="text-xs text-ink-muted">/ night</span></div></div><div className="flex items-center gap-2"><a href={`https://wa.me/254729000410?text=${encodeURIComponent(`Hi Good Secrets Safaris, I'm interested in booking ${hotel.name}. Please share the current seasonal rates and availability.`)}`} target="_blank" rel="noreferrer" aria-label={`Ask on WhatsApp about ${hotel.name}`} className="min-w-11 min-h-11 p-2 rounded-xl bg-action-soft text-action border border-action-border flex items-center justify-center"><MessageCircle className="w-5 h-5 text-emerald-700"/></a><Link href={`/hotels/${hotel.slug}`} aria-label={`View ${hotel.name}`} className="min-h-11 inline-flex items-center gap-1 px-4 py-2 rounded-xl bg-brand-strong hover:bg-brand-hover text-white text-sm font-bold transition-all shadow-sm">View Stay<ArrowRight className="w-4 h-4"/></Link></div></div></div></article>}

export function BlogCard({post}:{post:BlogPost}){return <article className="group rounded-2xl bg-white border border-border-strong overflow-hidden hover:border-brand hover:shadow-md transition-all flex flex-col"><Link href={`/blog/${post.slug}`} className="text-left flex flex-col flex-1"><div className="relative aspect-[16/10] overflow-hidden bg-surface-muted"><Image src={safeImage(post.featuredImage)} alt={post.title} fill sizes="(max-width:720px) 100vw,33vw" className="object-cover group-hover:scale-[1.03] transition-transform duration-500"/></div><div className="p-6 space-y-3 flex-1"><div className="flex items-center gap-2 text-xs font-bold text-brand-deep"><span>{post.category}</span><span>·</span><span className="text-ink-subtle">{post.readingTime}</span></div><h3 className="font-serif-luxury text-xl font-bold text-ink-strong group-hover:text-brand-hover transition-colors line-clamp-2">{post.title}</h3><p className="text-sm text-ink-muted line-clamp-3 leading-relaxed">{post.excerpt}</p></div><div className="px-6 pb-6 pt-4 flex items-center justify-between text-sm text-ink-subtle border-t border-border"><span>{post.author?.name}</span><span className="text-brand-deep font-bold flex items-center gap-1">Read guide <ArrowRight className="w-4 h-4"/></span></div></Link></article>}

export function ReviewCard({review}:{review:Testimonial}){return <article className="rounded-2xl border border-border-strong bg-white p-6 text-ink-strong shadow-sm"><div className="flex text-amber-600" aria-label={`${review.rating} out of 5 stars`}>{Array.from({length:Math.max(0,Math.min(5,Math.round(review.rating)))}).map((_,i)=><Star key={i} className="h-4 w-4 fill-current"/>)}</div><blockquote className="mt-4 font-serif-luxury text-lg leading-relaxed">“{review.reviewText}”</blockquote><footer className="mt-5 border-t border-border pt-4 text-sm"><strong className="block">{review.reviewerName}</strong><span className="text-ink-muted">{review.reviewerCountry} · {review.platform}</span></footer></article>}
